from pathlib import Path
import ast
source = Path('candidate.py').read_text()
for mode, filename in [('independent','histogram_independent.py'), ('repeat','histogram_repeat.py'), ('mean','histogram_mean.py')]:
    Path(filename).write_text(source.replace(\"'summary_mode': 'joint'\", \"'summary_mode': '\" + mode + \"'\", 1))
files = ['candidate.py','histogram_independent.py','histogram_repeat.py','histogram_mean.py']
allowed = {'math','torch','numpy','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
trees = []
for filename in files:
    source_text = Path(filename).read_text()
    compile(source_text, filename, 'exec')
    tree = ast.parse(source_text)
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            assert all(item.name.split('.')[0] in allowed for item in node.names)
        if isinstance(node, ast.ImportFrom):
            assert node.module.split('.')[0] in allowed
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            assert node.func.id not in {'open','exec','eval','__import__','compile'}
    trees.append(tree)
classes = [ast.dump(next(n for n in tree.body if isinstance(n,ast.ClassDef))) for tree in trees]
assert len(set(classes)) == 1
ancestor = ast.parse(Path('history_g0_r0003_global_mean.py').read_text())
def method(tree,name):
    cls = next(n for n in tree.body if isinstance(n,ast.ClassDef))
    return next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name == name)
def body_without_doc(tree,name):
    nodes = method(tree,name).body
    if isinstance(nodes[0],ast.Expr) and isinstance(nodes[0].value,ast.Constant):
        nodes = nodes[1:]
    return [ast.dump(n) for n in nodes]
assert body_without_doc(trees[0],'_evidence') == body_without_doc(ancestor,'_evidence')
def constructor_learned_nodes(tree):
    nodes = method(tree,'__init__').body
    start = next(i for i,n in enumerate(nodes) if isinstance(n,ast.Assign) and any(isinstance(t,ast.Attribute) and t.attr=='embeddings' for t in n.targets))
    return [ast.dump(n) for n in nodes[start:]]
assert constructor_learned_nodes(trees[0]) == constructor_learned_nodes(ancestor)
print('PASS: four modules compile; permitted imports; identical model classes; inherited evidence and learned construction ASTs match the global-mean ancestor.')
